/*
 * tests/test_nl_printf.c - unit tests for nl_vsnprintf / nl_snprintf
 *
 * Tests implementation behaviour, which diverges from C99 snprintf in one
 * intentional way: return value is number of chars written, not number that
 * would have been written if buffer were large enough
 *
 * Besides hand-written cases below, tests/printf_table.inc holds a few thousand
 * rows generated by tests/gen_printf_table.py with Python's %-formatting as
 * oracle (flags, width, precision, %f rounding, nan/inf)
 *
 * gcc -D__LINUX_NOLIBC__ -nostdlib -static  test_nl_printf.c \
 *           ../lib/nl_printf.c ../lib/nl_errno.c ../lib/nl_alloc.c \
 *           ../lib/nl_start.c -I../include -I../lib -o /tmp/test_nl_printf
 */
#include "../lib/nolibc.h"

// Test framework
static int _pass = 0;
static int _fail = 0;

// Render a byte string with control characters escaped
static const char *vis(const char *s, char *buf, size_t bufsz) {
  static const char hex[] = "0123456789abcdef";
  size_t j = 0;

  for (size_t i = 0; s[i] && j + 4 < bufsz; i++) {
    unsigned char c = (unsigned char)s[i];

    if (c == '\n') {
      buf[j++] = '\\';
      buf[j++] = 'n';
    } else if (c == '\t') {
      buf[j++] = '\\';
      buf[j++] = 't';
    } else if (c == '\r') {
      buf[j++] = '\\';
      buf[j++] = 'r';
    } else if (c < 0x20 || c == 0x7f) {
      buf[j++] = '\\';
      buf[j++] = 'x';
      buf[j++] = hex[(c >> 4) & 0xf];
      buf[j++] = hex[c & 0xf];
    } else {
      buf[j++] = (char)c;
    }
  }

  buf[j] = '\0';

  return buf;
}

static void _check_str(const char *got, const char *want, const char *label,
                       int line) {
  char buf[512];
  int ok = (nl_strcmp(got, want) == 0);
  int n;
  if (ok) {
    char shown[512];
    n = nl_snprintf(buf, sizeof(buf), "ok   [%3d] %s\n", line,
                    vis(label, shown, sizeof shown));
    _pass++;
  } else {
    n = nl_snprintf(buf, sizeof(buf),
                    "FAIL [%3d] %s\n"
                    "          got  = '%s'\n"
                    "          want = '%s'\n",
                    line, label, got, want);
    _fail++;
  }

  if (n > 0) {
    nl_write(1, buf, (size_t)n);
  }
}

static void _check_int(int got, int want, const char *label, int line) {
  char buf[256];
  int ok = (got == want);
  int n;
  if (ok) {
    char shown[512];
    n = nl_snprintf(buf, sizeof(buf), "ok   [%3d] %s\n", line,
                    vis(label, shown, sizeof shown));
    _pass++;
  } else {
    n = nl_snprintf(buf, sizeof(buf), "FAIL [%3d] %s: got=%d want=%d\n", line,
                    label, got, want);
    _fail++;
  }

  if (n > 0) {
    nl_write(1, buf, (size_t)n);
  }
}

// Formats with nl_snprintf, compares result to expected string
#define FMT_EQ(want, ...)                                                      \
  do {                                                                         \
    char _b[256];                                                              \
    int _n = nl_snprintf(_b, sizeof(_b), __VA_ARGS__);                         \
    _check_str(_b, (want), #__VA_ARGS__ " == \"" want "\"", __LINE__);         \
    (void)_n;                                                                  \
  } while (0)

// Return-value check: nl_snprintf returns chars written (not C99 would-have)
#define FMT_RET(size, want_ret, ...)                                           \
  do {                                                                         \
    char _b[(size)];                                                           \
    int _r = nl_snprintf(_b, (size), __VA_ARGS__);                             \
    _check_int(_r, (want_ret), "ret(" #__VA_ARGS__ ", sz=" #size ")",          \
               __LINE__);                                                      \
  } while (0)

// Test cases
static void test_percent_d(void) {
  FMT_EQ("0", "%d", 0);
  FMT_EQ("1", "%d", 1);
  FMT_EQ("-1", "%d", -1);
  FMT_EQ("42", "%d", 42);
  FMT_EQ("-42", "%d", -42);
  FMT_EQ("2147483647", "%d", 2147483647);   // INT_MAX
  FMT_EQ("-2147483648", "%d", -2147483648); // INT_MIN
  // Width: right-aligned with spaces
  FMT_EQ("   42", "%5d", 42);
  FMT_EQ("  -42", "%5d", -42);
  // Width smaller than value: no truncation
  FMT_EQ("12345", "%3d", 12345);
  FMT_EQ("00042", "%05d", 42);
  FMT_EQ("-0042", "%05d", -42);
  FMT_EQ("42   ", "%-5d", 42);
  FMT_EQ("+42", "%+d", 42);
  FMT_EQ(" 42", "% d", 42);
  FMT_EQ("00042", "%.5d", 42);
  FMT_EQ("", "%.0d", 0);
  FMT_EQ("  007", "%5.3d", 7);
  FMT_EQ("   42", "%*d", 5, 42);
  FMT_EQ("42   ", "%*d", -5, 42);
  FMT_EQ("  042", "%*.*d", 5, 3, 42);
  FMT_EQ("-1", "%hhd", 255);
  FMT_EQ("-1", "%hd", 65535);
  FMT_EQ("7", "%i", 7);
  FMT_EQ("12:05:09", "%d:%02d:%02d", 12, 5, 9);
}

static void test_percent_u(void) {
  FMT_EQ("0", "%u", 0u);
  FMT_EQ("42", "%u", 42u);
  FMT_EQ("4294967295", "%u", 4294967295u); // UINT_MAX
  FMT_EQ("   42", "%5u", 42u);             // right-aligned with spaces
}

static void test_percent_x(void) {
  FMT_EQ("0", "%x", 0u);
  FMT_EQ("ff", "%x", 0xffu);
  FMT_EQ("deadbeef", "%x", 0xdeadbeefu);
  FMT_EQ("a", "%x", 10u);
  FMT_EQ("   2a", "%5x", 42u);
  FMT_EQ("0002a", "%05x", 42u);
  FMT_EQ("2A", "%X", 42u);
  FMT_EQ("0x2a", "%#x", 42u);
  FMT_EQ("0", "%#x", 0u);
  FMT_EQ("0x0002a", "%#07x", 42u);
  FMT_EQ("17", "%o", 15u);
  FMT_EQ("017", "%#o", 15u);
  FMT_EQ("0", "%#o", 0u);
  FMT_EQ("", "%.0x", 0u);
}

static void test_percent_p(void) {
  FMT_EQ("(nil)", "%p", (void *)0);
  FMT_EQ("0x1234", "%p", (void *)0x1234);
  FMT_EQ("0xdeadbeef00", "%p", (void *)0xdeadbeef00UL);
  FMT_EQ("    (nil)", "%9p", (void *)0);
}

static void test_percent_f(void) {
  FMT_EQ("0.000000", "%f", 0.0);
  FMT_EQ("-0.000000", "%f", -0.0);
  FMT_EQ("3.141593", "%f", 3.14159265358979);
  FMT_EQ("59.9", "%.1f", 59.94);
  FMT_EQ("0", "%.0f", 0.5); // exact tie: round half to even
  FMT_EQ("2", "%.0f", 1.5);
  FMT_EQ("2", "%.0f", 2.5);
  FMT_EQ("4", "%.0f", 3.5);
  FMT_EQ("1.", "%#.0f", 1.0);
  FMT_EQ("10.0", "%.1f", 9.96);
  FMT_EQ("1000000.000000", "%f", 1e6);
  FMT_EQ("  3.14", "%6.2f", 3.14159);
  FMT_EQ("003.14", "%06.2f", 3.14159);
  FMT_EQ("-03.14", "%06.2f", -3.14159);
  FMT_EQ("3.14  ", "%-6.2f", 3.14159);
  FMT_EQ("+3.14", "%+.2f", 3.14159);
  FMT_EQ("nan", "%f", __builtin_nan(""));
  FMT_EQ("inf", "%f", __builtin_inf());
  FMT_EQ("-inf", "%f", -__builtin_inf());
  FMT_EQ("INF", "%F", __builtin_inf());
  FMT_EQ("10000000000000000000000.000000", "%f", 1e22);
  FMT_EQ("0.000000", "%f", 4.9e-324);
}

static void test_percent_s_prec(void) {
  FMT_EQ("hel", "%.3s", "hello");
  FMT_EQ("  hel", "%5.3s", "hello");
  FMT_EQ("hel  |", "%-5.3s|", "hello");
  FMT_EQ("", "%.0s", "hello");
  FMT_EQ("ab", "%.*s", 2, "abcdef");
  FMT_EQ("  x", "%3c", 'x');
  FMT_EQ("x  ", "%-3c", 'x');
}

static void test_unknown_and_edges(void) {
  FMT_EQ("?", "%q");
  FMT_EQ("50%", "%d%%", 50);
  FMT_EQ("ab", "ab%"); // lone trailing %
}

// Table-driven rows. Quiet on success so a failure is easy to spot.
static void row_check(const char *got, const char *want, const char *fmt,
                      int *bad) {
  if (nl_strcmp(got, want) != 0) {
    char shown[128];
    char line[512];
    int n = nl_snprintf(line, sizeof(line),
                        "FAIL fmt=\"%s\" got=\"%s\" want=\"%s\"\n", fmt,
                        vis(got, shown, sizeof(shown)), want);
    nl_write(1, line, (size_t)n);
    (*bad)++;
  }
}

static void test_oracle_table(void) {
  int bad = 0;
  int rows = 0;
  char b[1600];
#define ROW(call, f, want)                                                     \
  do {                                                                         \
    (call);                                                                    \
    row_check(b, (want), (f), &bad);                                           \
    rows++;                                                                    \
  } while (0)
#define ROW_I(f, a, want) ROW(nl_snprintf(b, sizeof(b), f, a), f, want);
#define ROW_U(f, a, want) ROW(nl_snprintf(b, sizeof(b), f, a), f, want);
#define ROW_D(f, a, want) ROW(nl_snprintf(b, sizeof(b), f, a), f, want);
#define ROW_S(f, a, want) ROW(nl_snprintf(b, sizeof(b), f, a), f, want);
#include "printf_table.inc"
#undef ROW_I
#undef ROW_U
#undef ROW_D
#undef ROW_S
#undef ROW
  _check_int(bad, 0, "oracle table: rows that differ from C", __LINE__);
  _check_int(rows > 3000, 1, "oracle table has rows", __LINE__);
}

static void test_percent_s(void) {
  FMT_EQ("hello", "%s", "hello");
  FMT_EQ("", "%s", "");
  FMT_EQ("(null)", "%s", (char *)0); // NULL -> "(null)"
  FMT_EQ("     hi", "%7s", "hi");    // right-aligned
  FMT_EQ("hi", "%2s", "hi");         // no truncation when value >= width
  FMT_EQ("hi", "%1s", "hi");
}

static void test_percent_c(void) {
  FMT_EQ("A", "%c", 'A');
  FMT_EQ("\n", "%c", '\n');
  FMT_EQ("%", "%%");
}

static void test_long(void) {
  FMT_EQ("0", "%ld", 0LL);
  FMT_EQ("-1", "%ld", -1LL);
  FMT_EQ("9223372036854775807", "%ld", 9223372036854775807LL); // LLONG_MAX
  FMT_EQ("0", "%lu", 0ULL);
  FMT_EQ("18446744073709551615", "%lu",
         18446744073709551615ULL); // ULLONG_MAX
}

static void test_length_modifiers(void) {
  FMT_EQ("0", "%zu", (size_t)0);
  FMT_EQ("2097152", "%zu", (size_t)2097152);
  FMT_EQ("18446744073709551615", "%zu", (size_t)18446744073709551615ULL);
  FMT_EQ("-5", "%zd", (long long)-5);
  FMT_EQ("18446744073709551615", "%llu", 18446744073709551615ULL);
  FMT_EQ("-9223372036854775807", "%lld", -9223372036854775807LL);
  // LLONG_MIN: negating it is UB for a signed value
  FMT_EQ("-9223372036854775808", "%ld", (-9223372036854775807LL - 1));
  FMT_EQ("ffffffffffffffff", "%lx", 18446744073709551615ULL);
  FMT_EQ("deadbeef00", "%lx", 0xdeadbeef00ULL);
  FMT_EQ("100000000", "%zx", (size_t)0x100000000ULL);
  FMT_EQ("   42", "%5ld", 42LL);
  // plain int arguments are still read as int
  FMT_EQ("-1", "%d", -1);
  FMT_EQ("4294967295", "%u", 4294967295u);
}

static void test_truncation(void) {
  // Return value = chars written (not C99 would have written)
  FMT_RET(1, 0, "%d", 42);         // size=1: only null terminator fits
  FMT_RET(3, 2, "%d", 42);         // size=3: "42\0" -> wrote 2
  FMT_RET(4, 3, "%d", 123);        // size=4: "123\0" -> wrote 3
  FMT_RET(3, 2, "%d", 123);        // size=3: "12\0" -> wrote 2
  FMT_RET(9, 8, "%s", "abcdefgh"); // fits exactly (8 chars + null)
  FMT_RET(5, 4, "%s", "abcdefgh"); // truncated: "abcd\0"

  // Null terminator always written within buffer
  {
    char buf[4] = {'X', 'X', 'X', 'X'};
    nl_snprintf(buf, 4, "%d", 99999);
    _check_int(buf[3], '\0', "truncated buf always null-terminated", __LINE__);
  }
}

static void test_combined(void) {
  // Multiple specifiers in one call
  FMT_EQ("x=1 y=2", "x=%d y=%d", 1, 2);
  FMT_EQ("hi there", "%s %s", "hi", "there");
  FMT_EQ("val=0xff", "val=0x%x", 0xff);
  // Literal %%
  FMT_EQ("100%", "%d%%", 100);
}

// Main
int main(int argc, char *argv[]) {
  (void)argc;
  (void)argv;

  test_percent_d();
  test_percent_u();
  test_percent_x();
  test_percent_s();
  test_percent_s_prec();
  test_percent_p();
  test_percent_f();
  test_unknown_and_edges();
  test_oracle_table();
  test_percent_c();
  test_long();
  test_length_modifiers();
  test_truncation();
  test_combined();

  char summary[128];
  int n = nl_snprintf(summary, sizeof(summary), "\n%d passed  %d failed\n",
                      _pass, _fail);
  nl_write(1, summary, (size_t)n);

  return _fail ? 1 : 0;
}
